{
    "predictors": [
        {
            "name": "Supplier Network Centrality",
            "construction": "Calculate the centrality of a firm's supplier network using data from supplier-disclosure filings and industry reports. Use network analysis to determine the centrality measure.",
            "rationale": "Firms central in supply networks may have better access to information and bargaining power, leading to enhanced competitive advantages.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Growth Rate",
            "construction": "Compute the year-over-year growth rate of the number of employees using data from company annual reports.",
            "rationale": "Rapid employee growth may signal expansion and investment in future growth opportunities.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Board Diversity Index",
            "construction": "Create an index measuring the diversity of a company's board of directors using gender, age, and ethnic diversity metrics obtained from corporate governance reports.",
            "rationale": "Diverse boards may lead to better decision-making and adaptability to market changes.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Product Innovation Score",
            "construction": "Score firms based on the number of new product launches reported in industry publications and press releases over the past year.",
            "rationale": "Frequent product innovations can indicate a firm's commitment to growth and market leadership.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Corporate Social Responsibility (CSR) Intensity",
            "construction": "Measure the intensity of CSR activities from annual reports and CSR disclosures, including environmental, social, and governance aspects.",
            "rationale": "Firms with strong CSR commitments may have lower risk profiles and better stakeholder relationships.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Satisfaction Index",
            "construction": "Aggregate ratings from customer satisfaction surveys and reviews reported in industry publications and online platforms like Epinions.",
            "rationale": "High customer satisfaction can lead to customer loyalty, repeat business, and stable cash flows.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Patent Citation Momentum",
            "construction": "Calculate the change in the number of citations of a firm's patents over the past three years using the US Patent Office database.",
            "rationale": "An increase in patent citations may reflect a firm's technological leadership and growth potential.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Management Tenure Average",
            "construction": "Compute the average tenure of the firm's top management team from data available in company bios and proxy statements.",
            "rationale": "Experienced management teams may provide stability and consistent strategic direction.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Insider Trading Intensity",
            "construction": "Calculate the volume of insider buying relative to selling over the past year using SEC Form 4 filings.",
            "rationale": "Significant insider buying may indicate management's confidence in the firm's future performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Supplier Dependency Ratio",
            "construction": "Measure the proportion of a firm's supplies sourced from its largest supplier using data from supplier-disclosure filings.",
            "rationale": "A lower dependency on key suppliers may reduce operational risk and improve bargaining power.",
            "higher_returns_for": "low values of the measure"
        }
    ]
}
